parameters.jsCode:
const res = $input.first().json;
const form = $('Settings').first().json;
const text = (res.body && res.body.choices && res.body.choices[0].message.content) || '';
const m = text.match(/\{[\s\S]*\}/);
let c = {};
try { c = JSON.parse(m ? m[0] : text); } catch (e) { c = { category: 'other', sentiment: 'neutral', urgency: 'medium', summary: '', tags: [] }; }
const pick = (v, allowed, dflt) => (allowed.includes(v) ? v : dflt);

// Cradler column names must be lowercase snake_case.
return [{ json: { row: {
  message: form['Your feedback'],
  area: form['Area'],
  email: form['Email'] || null,
  category: pick(c.category, ['bug', 'feature_request', 'complaint', 'question', 'praise', 'other'], 'other'),
  sentiment: pick(c.sentiment, ['positive', 'neutral', 'negative'], 'neutral'),
  urgency: pick(c.urgency, ['low', 'medium', 'high'], 'medium'),
  summary: String(c.summary || '').slice(0, 300),
  tags: Array.isArray(c.tags) ? c.tags.slice(0, 4).join(', ') : '',
  language: String(c.language || '').slice(0, 8),
  source: 'n8n form',
  classify_cost: Number(res.headers['x-apimodels-cost'] || 0),
} } }];

