  filters: [{ field: 'created_at', op: 'gte', value: new Date(Date.now() - ($json['Period'] === 'Last 30 days' ? 30 : 7) * 86400000).toISOString() }],
  order: [{ field: 'created_at', desc: true }],
  limit: 1000,
