}) }}

parameters.jsCode:
const res = $input.first().json;
const rows = res.rows || [];
const count = (key) => rows.reduce((m, r) => { const k = r[key] || 'unknown'; m[k] = (m[k] || 0) + 1; return m; }, {});
const tags = {};
for (const r of rows) for (const t of String(r.tags || '').split(',').map((s) => s.trim()).filter(Boolean)) tags[t] = (tags[t] || 0) + 1;
const topTags = Object.entries(tags).sort((a, b) => b[1] - a[1]).slice(0, 10);
// The model gets one compact line per message, newest first, at most 300.
const lines = rows.slice(0, 300).map((r) => `[${r.urgency}|${r.category}|${r.sentiment}|${r.area}] ${r.summary || String(r.message).slice(0, 160)}`);
return [{ json: {
  period: $('Settings').first().json['Period'],
  total: res.total ?? rows.length,
  by_category: count('category'), by_sentiment: count('sentiment'), by_urgency: count('urgency'), by_area: count('area'),
  top_tags: topTags,
  high: rows.filter((r) => r.urgency === 'high').slice(0, 10).map((r) => ({ when: r.created_at, area: r.area, message: r.message })),
  lines,
} }];

