const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const d = $('Count and sample').first().json;
const res = $input.first().json;
const report = (res.body && res.body.choices && res.body.choices[0].message.content) || '';
// Minimal rendering: "## " lines become headings, "- " lines become list items.
const body = esc(report).split('\n').map((l) => {
  if (/^#{1,3}\s/.test(l)) return `<h3>${l.replace(/^#{1,3}\s/, '')}</h3>`;
  if (/^\s*[-*•]\s/.test(l)) return `<li>${l.replace(/^\s*[-*•]\s/, '')}</li>`;
  return l.trim() ? `<p>${l}</p>` : '';
}).join('\n');
const chips = (obj) => Object.entries(obj).sort((a, b) => b[1] - a[1]).map(([k, v]) => `<span class="chip">${esc(k)} ${v}</span>`).join(' ');

const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>body{font-family:system-ui,-apple-system,Segoe UI,sans-serif;background:#f5f5f4;color:#1c1917;margin:0;padding:32px 16px}
.card{max-width:820px;margin:0 auto;background:#fff;border:1px solid #e7e5e4;border-radius:16px;padding:24px}
.chip{display:inline-block;margin:3px 2px;padding:3px 10px;border-radius:999px;background:#f5f5f4;border:1px solid #e7e5e4;font-size:13px}
.row{margin:6px 0}.meta{color:#78716c;font-size:13px}li{margin:4px 0 4px 18px}h3{margin:22px 0 6px}
.btn{display:inline-block;margin-top:16px;padding:9px 16px;border-radius:10px;background:#1c1917;color:#fff;text-decoration:none}</style></head>
<body><div class="card"><h2>Feedback report · ${esc(d.period)}</h2>
<p class="meta">${d.total} messages · report written by ${esc($('Settings').first().json.report_model)} for $${Number(res.headers['x-apimodels-cost'] || 0).toFixed(4)}</p>
<div class="row"><b>Category</b> ${chips(d.by_category)}</div>
<div class="row"><b>Sentiment</b> ${chips(d.by_sentiment)}</div>
<div class="row"><b>Urgency</b> ${chips(d.by_urgency)}</div>
<div class="row"><b>Area</b> ${chips(d.by_area)}</div>
${body}
<a class="btn" href="/form/feedback-report">New report</a></div></body></html>`;
return [{ json: { html } }];

